const rows = $input.first().json.rows;
const projectId = rows[0].project_id;

const performanceMetrics = {
  project_id: projectId,
  total_duration_seconds: rows[0].total_duration_seconds,
  overall_score: rows[0].overall_score,
  state_history: rows[0].state_history,
  error_log: rows[0].error_log,
  state: rows[0].state,
  reviews: rows.filter(r => r.review_id).map(r => ({
    type: r.review_type,
    score: r.review_score,
    feedback: r.feedback
  })),
  prompt_calls: rows.filter(r => r.prompt_id).map(r => ({
    prompt_text: r.prompt_text,
    response: r.response,
    tokens_used: r.tokens_used,
    latency_ms: r.latency_ms,
    backend: r.backend
  }))
};

return [{ json: { project_id: projectId, performance: performanceMetrics } }];

const input = $input.first().json;
const perf = input.performance;
const promptCalls = perf.prompt_calls || [];

const promptAnalysis = promptCalls.map(call => {
  const avgTokens = promptCalls.reduce((sum, c) => sum + (c.tokens_used || 0), 0) / promptCalls.length;
  const avgLatency = promptCalls.reduce((sum, c) => sum + (c.latency_ms || 0), 0) / promptCalls.length;

  return {
    prompt_preview: call.prompt_text?.substring(0, 100),
    tokens_used: call.tokens_used,
    latency_ms: call.latency_ms,
    backend: call.backend,
    efficiency: call.tokens_used > 0 ? (1000 / call.tokens_used) : 0,
    response_quality: call.response ? 'received' : 'missing'
  };
});

const backendStats = {};
promptCalls.forEach(call => {
  if (!backendStats[call.backend]) {
    backendStats[call.backend] = { count: 0, total_tokens: 0, total_latency: 0 };
  }
  backendStats[call.backend].count++;
  backendStats[call.backend].total_tokens += call.tokens_used || 0;
  backendStats[call.backend].total_latency += call.latency_ms || 0;
});

Object.keys(backendStats).forEach(backend => {
  backendStats[backend].avg_tokens = backendStats[backend].total_tokens / backendStats[backend].count;
  backendStats[backend].avg_latency = backendStats[backend].total_latency / backendStats[backend].count;
});

return [{ json: { ...input, prompt_analysis: promptAnalysis, backend_stats: backendStats } }];

const input = $input.first().json;
const backendStats = input.backend_stats;

const backendAnalysis = Object.keys(backendStats).map(backend => {
  const stats = backendStats[backend];
  const isEfficient = stats.avg_tokens < 2000 && stats.avg_latency < 5000;
  const isReliable = stats.count > 0;

  return {
    backend: backend,
    call_count: stats.count,
    avg_tokens: Math.round(stats.avg_tokens),
    avg_latency: Math.round(stats.avg_latency),
    efficiency_rating: isEfficient ? 'high' : 'low',
    reliability_rating: isReliable ? 'reliable' : 'unreliable',
    recommendation: isEfficient && isReliable ? 'keep' : 'consider_alternative'
  };
});

return [{ json: { ...input, backend_analysis: backendAnalysis } }];

const input = $input.first().json;
const perf = input.performance;

const lessons = [];

if (perf.overall_score >= 0.9) {
  lessons.push({ type: 'success', lesson: 'High quality output achieved', category: 'quality' });
} else if (perf.overall_score < 0.6) {
  lessons.push({ type: 'improvement', lesson: 'Output quality below threshold, review prompts and parameters', category: 'quality' });
}

if (perf.total_duration_seconds > 3600) {
  lessons.push({ type: 'improvement', lesson: 'Project took over 1 hour, consider parallelization', category: 'performance' });
}

if (perf.error_log && Object.keys(perf.error_log).length > 0) {
  lessons.push({ type: 'error', lesson: 'Errors occurred during processing', category: 'reliability', details: perf.error_log });
}

input.prompt_analysis.forEach(pa => {
  if (pa.efficiency < 0.5) {
    lessons.push({ type: 'improvement', lesson: `Low prompt efficiency: ${pa.prompt_preview}...`, category: 'prompt_optimization' });
  }
});

input.backend_analysis.forEach(ba => {
  if (ba.recommendation === 'consider_alternative') {
    lessons.push({ type: 'optimization', lesson: `Backend ${ba.backend} performing suboptimally`, category: 'backend' });
  }
});

return [{ json: { ...input, lessons: lessons, total_lessons: lessons.length } }];

const input = $input.first().json;

const tuningRecommendations = [];

if (input.backend_analysis.some(b => b.avg_latency > 10000)) {
  tuningRecommendations.push({
    parameter: 'timeout_threshold',
    current_value: 30000,
    recommended_value: 60000,
    reason: 'Backend latency exceeding timeout'
  });
}

if (input.lessons.some(l => l.category === 'quality' && l.type === 'improvement')) {
  tuningRecommendations.push({
    parameter: 'min_quality_score',
    current_value: 0.7,
    recommended_value: 0.8,
    reason: 'Quality issues detected, raising threshold'
  });
}

if (input.performance.total_duration_seconds > 7200) {
  tuningRecommendations.push({
    parameter: 'max_project_duration',
    current_value: 7200,
    recommended_value: 3600,
    reason: 'Projects taking too long, tightening deadline'
  });
}

return [{ json: { ...input, tuning_recommendations: tuningRecommendations } }];

